    """Case-insensitive whole-word fixed-string count — the semantics of
    `rg -i -w -F --count-matches`. Pure stdlib: no ripgrep binary on this box."""
    pat = re.compile(r"(?<![A-Za-z0-9_])" + re.escape(term) + r"(?![A-Za-z0-9_])", re.IGNORECASE)
    return len(pat.findall(text))


