342				if rr != nil && !readOnlySemanticCache {
343					// Retain only this repository's facts: the cache is keyed by
344					// (brainDir, branch), so a merged-in global fact would be filed
345					// under this repo's key. markForeign above makes retain skip
346					// them, so the full set can be passed here.
