368					}
369				}
370				recordReceipt := func() {
371					recordServedFacts(cmd.ErrOrStderr(), vitalityNow(opts), brainDir, resolvedBranch, "recall",
372						vitalityHead(cmd.Context(), opts.Runner, repoDir), query, factRecordIDs(matches))
373				}
374				if jsonOut {
375					// Recall's JSON envelope is fact-centric (top-level `facts`), so
376					// its fact-scoped keys stay unprefixed: `pending_reviews` and
377					// `locus_drift`. The brief report is a multi-domain object and
378					// prefixes the same concepts as `facts_pending_review` /
379					// `facts_locus_drift` to disambiguate. This per-surface split is
380					// intentional and kept as-is; we do not unify the keys.
381					out := map[string]any{"branch": resolvedBranch, "query": query, "facts": matches}
382					// A consumer that renders these has to be able to tell which
383					// facts came from outside this repository; the ids are the
384					// smallest way to say so without changing the fact shape that
385					// every existing reader binds to.
386					if ids := sortedGlobalFactIDs(matches, globalIDs); len(ids) > 0 {
387						out["global_fact_ids"] = ids
388					}
389					engine := recallRetrievalIdentity(!noSemantic, readOnlySemanticCache, rr)
390					out["retrieval_engine"] = engine
391					if engine.EffectiveEngine != "" {
392						out["effective_engine"] = engine.EffectiveEngine
393					}
394					if eligibility != nil {
395						eligibility.DeliveredCount = len(matches)
396						out["eligibility"] = eligibility
397					}
398					if len(drift) > 0 {
399						out["locus_drift"] = drift
400					}
401					if len(pendingReviews) > 0 {
402						out["pending_reviews"] = pendingReviews
403					}
404					if proposalsErr != nil && len(matches) > 0 {
405						out["warnings"] = []string{factReviewQueueUnavailableWarning}
406					}
407					if storeWarning != "" {
408						warnings, _ := out["warnings"].([]string)
409						out["warnings"] = append(warnings, storeWarning)
410					}
411					if len(matches) == 0 {
412						if note := emptyResultBlindSpotOnBranch(brainDir, resolvedBranch); note != "" && storeWarning == "" {
413							out["blind_spot"] = note
414						}
415					}
416					if err := writeJSON(cmd, out); err != nil {
417						return err
418					}
419					if len(matches) > 0 {
420						recordReceipt()
421					}
422					return nil
423				}
424				if len(matches) == 0 {
425					return writeText(cmd, func(out io.Writer) {
426						fmt.Fprintf(out, "no facts for %q on %s\n", query, resolvedBranch)
427						if storeWarning != "" {
428							fmt.Fprintln(out, "warning: "+storeWarning)
429						}

