113			(progress.CompleteSourceDigest != "" && !validSHA256Identity(progress.CompleteSourceDigest)) ||
114			(!progress.Pending && (!progress.ResetComplete || progress.CompleteSourceDigest != progress.SourceDigest)) ||
115			(progress.ErrorCode != "" && progress.ErrorCode != "memory_vector_sync_failed") {
116			return memoryVectorProgress{}, newMemoryVectorProgressLoadError(fmt.Errorf("vector progress has invalid identity or bounds"), header.SchemaVersion)
