//go:build brain_cgo

package cli

import (
	"database/sql"
	"testing"
)

// TestBrainCGOFTS5Compiled guards the build recipe: brain_cgo must be paired
// with mattn's sqlite_fts5 feature tag or every FTS index (history, facts,
// docs) silently degrades at runtime. A binary that fails this test was built
// with `-tags brain_cgo` alone.
func TestBrainCGOFTS5Compiled(t *testing.T) {
	db, err := sql.Open(sqliteDriverName, ":memory:")
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Exec(`CREATE VIRTUAL TABLE probe USING fts5(text)`); err != nil {
		t.Fatalf("FTS5 unavailable — build with -tags \"brain_cgo sqlite_fts5\": %v", err)
	}
}
----
//go:build !brain_cgo

package cli

// Default build: the pure-Go modernc driver, no cgo. This is the Stage 1b
// fallback path — `go build` with no tags produces the same stack 1a shipped
// (modernc + FTS5 + Model2Vec brute-force cosine), so a cgo-less build remains
// a working (degraded-recall) brain. The cgo stack lives behind the brain_cgo
// tag in sqlite_driver_cgo.go.

import (
	_ "modernc.org/sqlite"
)

// sqliteDriverName is the database/sql driver this build registers.
const sqliteDriverName = "sqlite"

// brainCGOBuild reports whether this binary runs the Stage 1b cgo stack.
const brainCGOBuild = false
