1	package entityindex
2	
3	import (
4		"context"
5		"encoding/hex"
6		"encoding/json"
7		"fmt"
8		"os"
9		"strings"
10		"time"
11	
12		"github.com/entireio/entire-brain/internal/providerdetail"
13	)
14	
15	// IdentityKey was used by the pre-release global migration. It is ignored;
16	// parser selection is local and must never be changed by a synced marker.
17	const IdentityKey = "brain:entities-identity-revision"
18	
19	// ProviderIdentity is an additive provider capability, separate from the wire
20	// schema and release version. Legacy providers omit it and use the empty value.
21	func ProviderIdentity(ctx context.Context, runner Runner, repo, binary string) (string, error) {
22		if runner == nil {
23			return "", fmt.Errorf("graph identity requires a command runner")
24		}
25		if ctx == nil {
26			ctx = context.Background()
27		}
28		if binary == "" {
29			binary = "entire"
30		}
31		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
32		defer cancel()
33		out, _, err := runner.Run(ctx, repo, binary, "graph", "version", "--json")
34		if err != nil {
35			return "", identityError(binary, err)
36		}
37		var info struct {
38			IdentityRevision string `json:"identity_revision"`
39		}
40		if err := json.Unmarshal(out, &info); err != nil {
41			return "", identityError(binary, err)
42		}
43		if len(info.IdentityRevision) > 128 || strings.ContainsAny(info.IdentityRevision, "\r\n\x00") {
44			return "", fmt.Errorf("invalid graph identity revision")
45		}
46		return info.IdentityRevision, nil
47	}
48	
49	// identityFailure carries the SUMMARISED text a reader sees while keeping the
50	// original error reachable, so errors.Is/errors.As on a context deadline or an
51	// exec.Error still work across the summarisation.
52	type identityFailure struct {
53		message string
54		cause   error
55	}
56	
57	func (e *identityFailure) Error() string { return e.message }
58	func (e *identityFailure) Unwrap() error { return e.cause }
59	
60	// identityError reports a failed `graph version --json` the way the semantic
61	// index reports the identical cause.
62	//
63	// It used to be fmt.Errorf("read graph identity revision: %w", err), which
64	// embedded the subprocess's entire stderr verbatim. When the entire-graph
65	// plugin is not installed that stderr is the host CLI's full --help screen,
66	// so a first run printed 60 lines of command groups ending in
67	// `Did you mean this? grant` -- implying the reader had mistyped a command
68	// they never typed -- twice, once in the progress line and once in the
69	// summary block, and pushed setup's real 12-line report below the fold.
70	// The semantic index already answered the same cause in one line naming the
71	// install step; this is that answer, from the same shared rule, so the two
72	// components cannot disagree. The "read graph identity revision" prefix is
73	// kept: callers and the doctor's provider axis match on it.
74	func identityError(binary string, err error) error {
75		detail := strings.TrimSpace(err.Error())
76		message := "read graph identity revision"
77		if summary := providerdetail.Summary(detail); summary != "" {
78			message += ": " + summary
79		}
80		// Detection runs against the FULL detail, never the summary, so the marker
81		// is still found when the host CLI prints it below its usage text -- and
82		// so is the host's own copy of the remedy, which MissingSuffix declines to
83		// repeat.
84		message += providerdetail.MissingSuffix(message, detail, binary, os.LookupEnv)
85		return &identityFailure{message: message, cause: err}
86	}
87	
88	// RevisionKey isolates parser-derived records without rewriting legacy keys.
89	// An empty revision retains the frozen producer contract for older peers.
90	func RevisionKey(key, revision string) string {
91		if revision == "" {
92			return key
93		}
94		return "brain:entities-revision:" + hexSegment(revision) + ":" + hexSegment(key)
95	}
96	
97	func originalRevisionKey(key, revision string) (string, bool) {
98		if revision == "" {
99			return key, !strings.HasPrefix(key, "brain:entities-revision:")
100		}
101		prefix := "brain:entities-revision:" + hexSegment(revision) + ":"
102		if !strings.HasPrefix(key, prefix) {
103			return "", false
104		}
105		raw, err := hex.DecodeString(strings.TrimPrefix(key, prefix))
106		return string(raw), err == nil
107	}
108	
109	// anyRevisionKey identifies source records when carrying history across revisions.
110	func anyRevisionKey(key string) string {
111		const prefix = "brain:entities-revision:"
112		if !strings.HasPrefix(key, prefix) {
113			return key
114		}
115		parts := strings.Split(strings.TrimPrefix(key, prefix), ":")
