	if err != nil {
		t.Fatalf("re-encode records: %v", err)
	}
	entry["records"] = repoisoned
	rewritten, err := json.Marshal(entry)
	if err != nil {
		t.Fatalf("re-encode cache entry: %v", err)
	}
	writeGzip(t, entries[0], append(rewritten, '\n'))
